import random
from collections import defaultdict

def greedy_bipartite(a_size, b_size, seed=None):
    if seed is not None:
        random.seed(seed)
    A = list(range(a_size))
    B = list(range(a_size, a_size + b_size))
    adj = {v: set() for v in A + B}
    edges = []
    possible = [(a, b) for a in A for b in B]
    random.shuffle(possible)

    for a, b in possible:
        # Check C4: a-b'-a'-b-a
        # i.e., exists a' in A, b' in B such that a-b', a'-b', a'-b are edges
        # Since we add (a,b), we need to avoid a' != a, b' != b with (a,b'), (a',b'), (a',b) in adj
        ok = True
        for bp in adj[a]:
            # bp is a neighbor of a in B
            for ap in adj[bp]:
                if ap != a and b in adj[ap]:
                    ok = False
                    break
            if not ok:
                break
        if not ok:
            continue

        # Check C6: a-b-a2-b2-a3-b3-a? Wait, adding (a,b) closes a 6-cycle if there is a path b-a2-b2-a3-b3-a of length 5.
        # So we need to check for any a2 in adj[b], b2 in adj[a2] \ {b}, a3 in adj[b2] \ {a2}, b3 in adj[a3] \ {b2}, such that a in adj[b3].
        # In other words, b - a2 - b2 - a3 - b3 - a is a path.
        ok = True
        for a2 in adj[b]:
            for b2 in adj[a2]:
                if b2 == b:
                    continue
                for a3 in adj[b2]:
                    if a3 == a2:
                        continue
                    for b3 in adj[a3]:
                        if b3 == b2:
                            continue
                        if a in adj[b3]:
                            # found a 6-cycle: a - b - a2 - b2 - a3 - b3 - a
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    break
            if not ok:
                break
        if not ok:
            continue

        # Also need to check C6 where the new edge is not the first but some other position? 
        # Actually any 6-cycle that includes the new edge (a,b) can be rotated so that (a,b) is the first edge.
        # Since the graph is bipartite, the cycle alternates A-B-A-B-A-B.
        # Starting at a (in A), going to b (in B), then a2, b2, a3, b3, back to a.
        # This covers all cycles containing (a,b). So the check above is sufficient.

        adj[a].add(b)
        adj[b].add(a)
        edges.append((a, b))

    return edges, adj

