from itertools import permutations

def normalize_cycle(cycle):
    # cycle is a tuple of 5 vertices
    # Find the lexicographically smallest rotation
    best = cycle
    for i in range(1, 5):
        rot = cycle[i:] + cycle[:i]
        if rot < best:
            best = rot
    # Also try reverse
    rev = cycle[::-1]
    for i in range(5):
        rot = rev[i:] + rev[:i]
        if rot < best:
            best = rot
    return best

