import random
from collections import deque

def check_girth_if_added(graph, n, u, v, max_girth=8):
    """Check if adding edge (u,v) would create a cycle of length < max_girth."""
    # We need to check if there's already a path from u to v of length < max_girth - 1
    # BFS from u, but don't go through v
    target = v
    max_dist = max_girth - 2  # path length must be at most max_girth - 2

    dist = {u: 0}
    q = deque([u])

    while q:
        curr = q.popleft()
        if dist[curr] >= max_dist:
            continue
        for neighbor in graph[curr]:
            if neighbor == target:
                # Found a path from u to v
                path_len = dist[curr] + 1
                if path_len < max_girth - 1:
                    return False
                # If path_len == max_girth - 1, adding edge creates cycle of length max_girth, which is OK
                continue
            if neighbor not in dist:
                dist[neighbor] = dist[curr] + 1
                q.append(neighbor)

    return True

def build_graph_greedy(n, target_edges, max_girth=8, seed=None):
    if seed is not None:
        random.seed(seed)

    graph = {i: set() for i in range(n)}
    edges = []

    all_pairs = [(i, j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(all_pairs)

    for u, v in all_pairs:
        if len(edges) >= target_edges:
            break
        if check_girth_if_added(graph, n, u, v, max_girth):
            graph[u].add(v)
            graph[v].add(u)
            edges.append((u, v))

    return edges, graph

