import random
from collections import deque

def bfs_dist(graph, n, start):
    """Return distances from start in graph."""
    dist = [-1] * n
    dist[start] = 0
    q = deque([start])
    while q:
        u = q.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist

def get_girth_if_added(graph, n, u, v):
    """Return the length of the shortest cycle created by adding edge (u,v), or infinity if none."""
    dist = bfs_dist(graph, n, u)
    if dist[v] == -1:
        return float('inf')  # No path, no cycle created
    return dist[v] + 1  # Cycle length = path length + 1

def build_with_path_base(n, target_edges, max_girth=8, seed=None):
    if seed is not None:
        random.seed(seed)

    # Start with path 0-1-2-...-(n-1)
    graph = {i: set() for i in range(n)}
    edges = []
    for i in range(n-1):
        graph[i].add(i+1)
        graph[i+1].add(i)
        edges.append((i, i+1))

    # Try to add edges (i,j) where |i-j| >= max_girth - 1
    candidates = []
    for i in range(n):
        for j in range(i+1, n):
            if j - i >= max_girth - 1:
                candidates.append((i, j))

    random.shuffle(candidates)

    for u, v in candidates:
        if len(edges) >= target_edges:
            break
        girth = get_girth_if_added(graph, n, u, v)
        if girth >= max_girth:
            graph[u].add(v)
            graph[v].add(u)
            edges.append((u, v))

    return edges, graph

