def build_with_star_base(n, target_edges, max_girth=8, seed=None):
    if seed is not None:
        random.seed(seed)

    # Star centered at 0: edges (0, i) for i=1..n-1
    graph = {i: set() for i in range(n)}
    edges = []
    for i in range(1, n):
        graph[0].add(i)
        graph[i].add(0)
        edges.append((0, i))

    # Try to add edges between leaves
    candidates = []
    for i in range(1, n):
        for j in range(i+1, n):
            candidates.append((i, j))

    random.shuffle(candidates)

    for u, v in candidates:
        if len(edges) >= target_edges:
            break
        girth = get_girth_if_added(graph, n, u, v)
        if girth >= max_girth:
            graph[u].add(v)
            graph[v].add(u)
            edges.append((u, v))

    return edges, graph

